package webhook

import "strings"

// mentionsBot reports whether text names the bot account.
// The trigger is a case-insensitive substring, with no word boundary.
func mentionsBot(text, username string) bool {
	if username == "" {
		return false
	}
	if text == "" {
		return false
	}
	return strings.Contains(strings.ToLower(text), strings.ToLower(username))
}
